/* Actual Traveling post122/controller composed before Instrument source post128. */
import fs from'node:fs';import vm from'node:vm';import{createInstrumentSpellsEngine}from'./instrument-spells-native.mjs';import{bagNativeData}from'./bag-tricks-native.mjs';import*as goats from'../../src/data/lib/travel-goat.js';
const read=p=>fs.readFileSync(new URL('../../src/'+p,import.meta.url),'utf8'),strip=s=>s.replace(/^import [^\n]*\n/gm,'').replace(/export /g,'');
export function createInstrumentTravelEngine(){let peer;const e=createInstrumentSpellsEngine({inventory:[{n:'Instrument of the Bards (Canaith mandolin)',q:1,eq:true,attuned:true},{n:'Figurine of Wondrous Power',q:1,eq:false}],beforeInstrumentPost:ctx=>{if(peer)peer.run(ctx)}}),c=e.c;c.goats=goats;c.genv.QREFS={monster:structuredClone(bagNativeData.references)};const groups=[];c.registerSheetGroup=g=>groups.push(g);vm.runInContext(strip(read('builder/12zf-logic-travel-goat.js')),c);peer=groups.find(g=>g.id==='travel-goat-sources');e.setC(e.project());vm.runInContext('(function(){'+strip(read('builder/25r-logic-travel-goat.js'))+'})()',c);return {...e,c,get C(){return e.C},travelCommand:(kind,body)=>{const info=c.genv.__bldTravelGoatInfo(e.C.name),token=c.genv.__bldTravelGoatCapture(e.C.name,{signature:info.signature});return c.genv.__bldTravelGoatCommand(token,kind,body,e.before,()=>true)}};}
